"use strict";
// Generated by connect/tools/export_web.py: lets the unchanged Meridies pages run as plain website files.
//   - read-only API answers come from data/api/*.json (saved at export time)
//   - recordings, images, scan views and prepared voice clips come from media/
//   - the live calls (Meri chat, hearing, new voice lines, what's around, tell me more) go to the /api function
//   - anything that would change data answers 403: this copy is read-only
(() => {
  const C = /*__CONFIG__*/null;
  const STATIC_GET = new Set(C.staticGet), DYNAMIC = new Set(C.dynamic), SKIP = new Set(C.skipParams);
  const VOICE_KEYS = new Set(C.voiceKeys);
  const READ_ONLY = "This is the read-only web copy of Meridies. Recording, sharing and settings need the local server.";

  // SHA-1 of a UTF-8 string, hex. Synchronous, so audio/image src can be rewritten on the spot.
  function sha1(text) {
    const b = new TextEncoder().encode(text), n = (((b.length + 8) >> 6) + 1) * 16, w = new Array(n).fill(0);
    for (let i = 0; i < b.length; i++) w[i >> 2] |= b[i] << (24 - (i % 4) * 8);
    w[b.length >> 2] |= 0x80 << (24 - (b.length % 4) * 8);
    w[n - 1] = b.length * 8;
    let h0 = 0x67452301, h1 = 0xefcdab89, h2 = 0x98badcfe, h3 = 0x10325476, h4 = 0xc3d2e1f0;
    const x = new Array(80), rol = (v, s) => (v << s) | (v >>> (32 - s));
    for (let i = 0; i < n; i += 16) {
      for (let t = 0; t < 80; t++) x[t] = t < 16 ? w[i + t] | 0 : rol(x[t - 3] ^ x[t - 8] ^ x[t - 14] ^ x[t - 16], 1);
      let a = h0, bb = h1, c = h2, d = h3, e = h4;
      for (let t = 0; t < 80; t++) {
        const f = t < 20 ? (bb & c) | (~bb & d) : t < 40 ? bb ^ c ^ d : t < 60 ? (bb & c) | (bb & d) | (c & d) : bb ^ c ^ d;
        const k = t < 20 ? 0x5a827999 : t < 40 ? 0x6ed9eba1 : t < 60 ? 0x8f1bbcdc : 0xca62c1d6;
        const tmp = (rol(a, 5) + f + e + k + x[t]) | 0;
        e = d; d = c; c = rol(bb, 30); bb = a; a = tmp;
      }
      h0 = (h0 + a) | 0; h1 = (h1 + bb) | 0; h2 = (h2 + c) | 0; h3 = (h3 + d) | 0; h4 = (h4 + e) | 0;
    }
    return [h0, h1, h2, h3, h4].map((v) => (v >>> 0).toString(16).padStart(8, "0")).join("");
  }

  // same name connect/tools/export_web.py gave the saved answer
  function snapKey(u) {
    let name = u.pathname.replace(/^\/api\//, "").replace(/\/+$/, "").replace(/\//g, "_");
    const items = [...u.searchParams].filter(([k]) => !SKIP.has(k))
      .sort(([a, av], [b, bv]) => (a < b ? -1 : a > b ? 1 : av < bv ? -1 : av > bv ? 1 : 0));
    if (items.length) name += "__" + items.map(([k, v]) => `${k}-${v.replace(/[^A-Za-z0-9_.-]/g, "_")}`).join("__");
    return `/data/api/${name}.json`;
  }

  const local = (raw) => { try { const u = new URL(raw, location.href); return u.origin === location.origin ? u : null; } catch (_) { return null; } };

  // a server media URL -> its static file, or null when it is not one (or is not in this copy)
  function mediaUrl(raw) {
    if (typeof raw !== "string" && !(raw instanceof URL)) return null;
    const u = local(String(raw));
    if (!u) return null;
    const p = u.pathname, q = u.searchParams;
    let m = p.match(/^\/api\/memories\/([0-9a-f]{32})\/(audio|cover|image\/(\w+))$/);
    if (m) {
      if (m[2] === "audio") return C.audio[m[1]] ? `/media/memories/${m[1]}/audio.${C.audio[m[1]]}` : null;
      return `/media/memories/${m[1]}/${m[3] || "cover"}.jpg`;
    }
    if (p === "/api/view" && q.get("building") && q.get("sweep")) {
      const h = Number(q.get("heading") || 0), k = Math.round((((-h) % 360) + 360) % 360 / 90) % 4;
      return `/media/views/${q.get("building")}/${q.get("sweep")}_${k}.jpg`;
    }
    if (p === "/api/voice" && q.get("text")) {
      const key = sha1(`v${C.promptVersion}|${C.voiceName}|${q.get("style") || "calm"}|${q.get("text").trim()}`).slice(0, 20);
      return VOICE_KEYS.has(key) ? `/media/voice/${key}.mp3` : null;   // a new line: the function makes it
    }
    if (p === "/scene-samples.json") return "/data/scene-samples.json";
    return null;
  }
  const rewrite = (v) => mediaUrl(v) || v;

  const json = (status, body) => new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json" } });
  const realFetch = window.fetch.bind(window);
  window.fetch = function (input, init) {
    const req = input instanceof Request ? input : null;
    const u = local(req ? req.url : String(input));
    if (!u) return realFetch(input, init);
    const method = String((init && init.method) || (req && req.method) || "GET").toUpperCase();
    const signal = (init && init.signal) || (req && req.signal) || undefined;
    if (method === "GET") {
      const media = mediaUrl(u.href);
      if (media) return realFetch(media, { signal });
    }
    if (!u.pathname.startsWith("/api/")) return realFetch(input, init);
    const parts = u.pathname.split("/").filter(Boolean);
    if (method === "GET" && parts.length === 2 && STATIC_GET.has(parts[1])) {
      return realFetch(snapKey(u), { signal }).then((r) => (r.ok ? r : json(404, { error: "Not part of this web copy." })));
    }
    if (DYNAMIC.has(`${method} ${u.pathname}`)) return realFetch(input, init);
    if (method === "GET") return Promise.resolve(json(404, { error: "Not part of this web copy." }));
    return Promise.resolve(json(403, { error: READ_ONLY }));
  };

  // <audio>, <img>, links and new Audio(url) never pass through fetch: rewrite their URLs as they are set
  const RealAudio = window.Audio;
  window.Audio = function Audio(src) { return src === undefined ? new RealAudio() : new RealAudio(rewrite(src)); };
  window.Audio.prototype = RealAudio.prototype;
  for (const [proto, prop] of [[HTMLMediaElement.prototype, "src"], [HTMLImageElement.prototype, "src"],
                               [HTMLSourceElement.prototype, "src"], [HTMLAnchorElement.prototype, "href"]]) {
    const d = Object.getOwnPropertyDescriptor(proto, prop);
    if (d && d.set) Object.defineProperty(proto, prop, { ...d, set(v) { d.set.call(this, rewrite(v)); } });
  }
  const setAttribute = Element.prototype.setAttribute;
  Element.prototype.setAttribute = function (name, value) {
    return setAttribute.call(this, name, name === "src" || name === "href" ? rewrite(value) : value);
  };

  // the hat's live streams exist only next to the hat: a quiet, closed stream instead of endless retries
  const RealES = window.EventSource;
  if (RealES) {
    window.EventSource = function EventSource(url, opts) {
      const u = local(String(url));
      if (!u || !u.pathname.startsWith("/api/")) return new RealES(url, opts);
      const es = new EventTarget();
      return Object.assign(es, { url: u.href, readyState: 2, withCredentials: false, close() {},
                                 onopen: null, onmessage: null, onerror: null, CONNECTING: 0, OPEN: 1, CLOSED: 2 });
    };
    Object.assign(window.EventSource, { CONNECTING: 0, OPEN: 1, CLOSED: 2 });
  }
  window.MeridiesStatic = { mediaUrl, snapKey, sha1, readOnly: READ_ONLY };
})();
